(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzl-sj-prepa-ped-j8-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzl-sj-prepa-ped-j8-idesfm\",\n \"titre\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 49,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n     \"slug\": \"prepa-ped-j8-idesfm\",\n     \"pages\": \"\",\n     \"count\": 49,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie réalisée au 2e trimestre de la grossesse recherche, au plan médical :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une malformation fœtale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le sexe de l'enfant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le risque de trisomie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La confirmation de la grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une malformation fœtale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'échographie du 2e trimestre (vers 22 SA) est l'échographie morphologique : elle recherche les malformations fœtales. Le risque de trisomie (clarté nucale) relève du 1er trimestre. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours du bilan prénatal, dame G.G. avait une glycémie à jeun de 1,4 g/L et n'a pas été suivie en milieu spécialisé. Son nouveau-né a un poids de naissance de 4250 g. Dans les 48 premières heures de vie, le nouveau-né de dame G.G. court le risque de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypocalcémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hypoglycémie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hypercalcémie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hyperglycémie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Hypoglycémie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une glycémie à jeun de 1,4 g/L non suivie et un poids > 4000 g font évoquer un nouveau-né de mère diabétique. L'hyperinsulinisme fœtal persiste après la section du cordon : le risque principal est l'hypoglycémie. Remarque : dans le sujet, l'énoncé nomme la mère « dame G.G. » puis « dame T.S. » ; il s'agit de la même patiente.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né de mère diabétique », Physiopathologie – Après la naissance ; Problèmes\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le débit d'oxygène prescrit par le médecin chez le nouveau-né de 33 semaines d'aménorrhée en détresse respiratoire est compris entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,5 et 1 litre/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1 et 2 litres/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2 et 3 litres/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 0,5 et 1 litre/min\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez le prématuré, l'oxygène se donne à 0,5 l/min (1 l/min chez le nouveau-né à terme), soit entre 0,5 et 1 l/min, en surveillant la saturation. Remarque : le cours du Dr Asse propose 1 à 2 l/min aux lunettes ; la correction suit le module de néonatologie. Remarque : dans le sujet, cette question ne compte que 3 options (A, B, C).\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre III « Réanimation en salle de naissance », Ventilation en pression positive\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"T.P., né à terme, 60 minutes de vie, respiration rapide. À l'examen, je retrouve que T.P. a le thorax immobile lors de la respiration, un tirage intense et sus-sternal, un geignement audible à distance, un entonnoir xiphoïdien modéré, un battement des ailes du nez intense. Je conclus que T.P. a un score de Silverman à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"7\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"9\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 8\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Score de Silverman : thorax immobile = 1 ; tirage intense = 2 ; geignement audible à distance = 2 ; entonnoir xiphoïdien modéré = 1 ; battement des ailes du nez intense = 2. Total = 8 (détresse respiratoire sévère).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Détresse respiratoire du nouveau-né », Tableau du score de Silverman\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions de prévention suivantes, une seule favorise la prévention du spina bifida. Cochez cette proposition.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Acide folique à la gestante au 1er trimestre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Acide folique à la gestante au 2e trimestre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fer à la gestante au 2e trimestre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fer à la gestante au 1er trimestre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Acide folique à la gestante au 1er trimestre\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le spina bifida est un défaut de fermeture du tube neural lié au manque d'acide folique au moment de la conception et de l'embryogenèse : la prévention repose sur l'acide folique avant et au début de la grossesse (1er trimestre). Le fer prévient l'anémie.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XVIII « Malformations diagnostiquées à la naissance », Spina bifida\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant la crevasse de la mère allaitante, je prescris :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Conseils d'hygiène + antiparasitaire + antalgique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Conseils d'hygiène + antibiotique + corticoïde local\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Conseils d'hygiène + antiprurigineux + anti-inflammatoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Conseils d'hygiène + antiseptique + antalgique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Conseils d'hygiène + antiseptique + antalgique\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Devant des crevasses, on prescrit à la mère un antiseptique local et un antalgique, avec des conseils d'hygiène et de bonne position au sein.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Allaitement maternel », Problèmes et solutions (tableau)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paludisme est grave si mon enfant a :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une fièvre à 40 °C\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vomi plus de deux fois en une journée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Convulsé plus de deux fois en une journée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Émis des urines claires abondantes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Convulsé plus de deux fois en une journée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les convulsions à répétition sont un critère clinique de gravité du paludisme. Une fièvre à 40 °C seule ou deux vomissements ne suffisent pas à classer le paludisme grave.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Paludisme grave – Manifestations cliniques de gravité\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les deux principaux germes de l'infection postnatale du nouveau-né sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pneumocoque + méningocoque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Haemophilus influenzae + staphylocoque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Shigella + Escherichia coli\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vibrion cholérique + salmonelle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Haemophilus influenzae + staphylocoque\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'infection postnatale (tardive) est transmise par les mains et le matériel souillés ; le staphylocoque est un germe majeur. Les autres couples proposés sont des germes de diarrhée ou de méningite de l'enfant plus grand. Remarque : le module cite comme germes postnatals les staphylocoques et les bacilles Gram négatif (Klebsiella, Pseudomonas, entérobactéries) ; Haemophilus influenzae n'y figure pas (explication partiellement hors cours du projet).\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XII « Infections néonatales », Germes – Infections post-natales\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous êtes dans un hôpital de référence et vous recevez un grand enfant qui a un paludisme grave. Le traitement antipaludique de 1re intention est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Artésunate 2,4 mg/kg\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Artéméther 3,2 mg/kg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sels de quinine 8 mg/kg\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Luméfantrine 24 mg/kg\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Artésunate 2,4 mg/kg\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'artésunate injectable est actuellement la molécule recommandée en 1re intention pour le paludisme grave : 2,4 mg/kg à H0, H12, H24 puis toutes les 24 heures. La quinine et l'artéméther sont des alternatives.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Intérêt – Thérapeutique ; Rôle de soins curatifs\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour apprécier le risque de trisomie, le radiologue mesure à l'échographie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La longueur de l'humérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le diamètre bipariétal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La clarté au niveau de la nuque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La circonférence du crâne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La clarté au niveau de la nuque\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le risque de trisomie 21 s'apprécie à l'échographie par la mesure de la clarté nucale (épaisseur de la nuque) au 1er trimestre. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont des signes retrouvés au cours du paludisme grave de l'enfant sauf un. Cochez ce signe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ictère franc\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anémie sévère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Urines rouge porto\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Selles glairo-sanglantes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Selles glairo-sanglantes\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Ictère franc, anémie sévère et urines rouge porto (hémoglobinurie) sont des signes du paludisme grave. Les selles glairo-sanglantes évoquent une dysenterie (shigellose), pas le paludisme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Paludisme grave – Manifestations cliniques de gravité\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne tardive du nouveau-né survient entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"J0 et J2 de vie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"J8 et J28 de vie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"J3 et J7 de vie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"J2 et J3 de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. J8 et J28 de vie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'infection tardive (postnatale) survient après le 7e jour, jusqu'à la fin de la période néonatale (J8-J28).\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XII « Infections néonatales », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les examens suivants sont ceux prescrits en routine par l'agent de santé pour surveiller la grossesse sauf un. Cochez cet examen.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Groupe sanguin ABO/Rhésus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémogramme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sérologie hépatite B\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sérologie rubéole\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Sérologie hépatite B\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le bilan prénatal recommandé comprend groupe sanguin-rhésus, hémogramme/Emmel, sérologies syphilis et VIH, glycémie ; les sérologies toxoplasmose et rubéole sont aussi demandées. La correction nationale considère la sérologie hépatite B comme non systématique. Remarque : le module de néonatologie classe l'AgHBs et la sérologie rubéole ensemble parmi les « examens souhaités ».\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre IV « Soins essentiels aux nouveau-nés », Soins maternels\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont des facteurs vitamine K1-dépendants impliqués dans la maladie hémorragique du nouveau-né, sauf un. Cochez ce facteur.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Facteur VII\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Facteur X\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Facteur IV\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Facteur IX\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Facteur IV\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les facteurs de la coagulation vitamine K-dépendants sont les facteurs II, VII, IX et X (explorés par le temps de Quick). Le facteur IV (calcium) n'en fait pas partie.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Maladie hémorragique du nouveau-né », Laboratoire – Temps de Quick\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'espèce de Plasmodium la plus fréquemment responsable de paludisme grave en Côte d'Ivoire est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plasmodium ovale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plasmodium malariae\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Plasmodium falciparum\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Plasmodium vivax\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Plasmodium falciparum\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, Plasmodium falciparum est retrouvé dans près de 98 % des cas et c'est la seule espèce responsable des formes graves.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont des causes de prématurité induite, sauf une. Cochez cette cause.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accès palustre simple\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Souffrance fœtale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Éclampsie sévère\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Placenta prævia\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Accès palustre simple\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La prématurité induite résulte d'une décision médicale pour sauver la mère ou le fœtus : souffrance fœtale, toxémie/éclampsie, placenta prævia hémorragique, RCIU… Un accès palustre simple se traite et ne justifie pas un accouchement provoqué.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né prématuré », Causes induites ou provoquées ; Module de néonatologie (Néonatalogie), Chapitre VIII\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À l'examen, vous retrouvez que B.B.L. est irritable, ses yeux sont très enfoncés, les larmes sont absentes lors des pleurs, il est incapable de boire, sa bouche est très sèche et le pli cutané s'efface lentement. Vous concluez chez B.B.L. à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Signes évidents de déshydratation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Signes modérés de déshydratation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Signes légers de déshydratation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Signes sévères de déshydratation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Signes sévères de déshydratation\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Incapable de boire, yeux très enfoncés, bouche très sèche, larmes absentes, pli qui s'efface lentement : au moins deux signes de la colonne « sévère » sont présents, donc signes sévères de déshydratation (plan C).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Diagnostic de gravité (tableau)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"P.J., âgé de 5 mois, présente une diarrhée depuis 4 jours avec absence de signes de déshydratation. La dose de zinc comprimé à administrer à P.J. est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5 mg par voie orale pendant 10 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 mg par voie orale pendant 10 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20 mg par voie orale pendant 10 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"25 mg par voie orale pendant 10 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 10 mg par voie orale pendant 10 jours\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Avant 6 mois : ½ comprimé de zinc à 20 mg, soit 10 mg par jour par voie orale, pendant 10 à 14 jours.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan A », Donner du zinc\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"J.K., enfant de 3 ans pesant 15 kg, présente des signes évidents de déshydratation. Pour le réhydrater, je lui administre durant 4 heures du SRO à la quantité de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1125 mL\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"750 mL\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"450 mL\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1050 mL\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 1125 mL\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes évidents de déshydratation : plan B, 75 ml/kg de SRO en 4 heures. 75 × 15 kg = 1125 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan B », quantité de SRO (poids × 75)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né L.M. est né à 03 h 25 min. Je lui administre en intramusculaire de la vitamine K1 entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"03 h 25 et 03 h 55\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"03 h 56 et 04 h 25\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"04 h 26 et 04 h 55\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"04 h 56 et 05 h 25\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 04 h 26 et 04 h 55\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La vitamine K1 s'administre entre la 60e et la 90e minute de vie, après l'heure de contact peau à peau et la première tétée. Né à 03 h 25 : entre 04 h 25 et 04 h 55.\\n\\nSource : Cours de santé infantile L1 IDE-SFM, « Soins essentiels aux nouveau-nés », Technique de soins – 60-90 minutes de vie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fièvre désigne l'élévation de la température corporelle prise par voie rectale, le matin à distance des repas, supérieure à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"37,5 °C\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"38 °C\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"38,5 °C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"37,8 °C\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 37,5 °C\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fièvre est définie par une température rectale supérieure à 37,5 °C le matin (38 °C le soir).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né G.K. est né par césarienne. G.K. présente immédiatement après la naissance une détresse respiratoire. La principale cause de la détresse respiratoire de G.K. est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Trouble de résorption du liquide pulmonaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Maladie des membranes hyalines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inhalation du liquide amniotique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection bactérienne néonatale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Trouble de résorption du liquide pulmonaire\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après une césarienne (surtout sans travail), le liquide pulmonaire n'est pas chassé par la compression thoracique : retard de résorption du liquide pulmonaire (tachypnée transitoire). La maladie des membranes hyalines concerne surtout le prématuré. Remarque : dans le sujet, l'option A est coupée sur deux lignes (« Trouble de résorption du liquide » / « pulmonaire ») ; elle a été réunie.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre II « Adaptation à la vie extra-utérine », Elimination du liquide pulmonaire ; Chapitre V, Tachypnée transitoire\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nouveau-né GG, 3 jours de vie, vit à Krindjabo. La mère est très inquiète car le sexe de l'enfant est ambigu et il respire difficilement. Le médecin pense à une hyperplasie congénitale des surrénales.\",\n       \"text\": \"L'analyse des données révèle dans l'identification :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 données d'indépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 données d'indépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2 données d'indépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 donnée d'indépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 3 données d'indépendance\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les données d'identification (nom, âge, lieu d'habitation, sexe) sont habituellement des données d'indépendance. Ici, GG, 3 jours et Krindjabo sont des données d'indépendance (3) ; le sexe ambigu est une donnée de dépendance.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diagnostic infirmier », Collecte des données – Identification\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nouveau-né GG, 3 jours de vie, vit à Krindjabo. La mère est très inquiète car le sexe de l'enfant est ambigu et il respire difficilement. Le médecin pense à une hyperplasie congénitale des surrénales.\",\n       \"text\": \"Le principal agent infectieux de la diarrhée aiguë du nourrisson est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bactérien\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Parasitaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Viral\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mycosique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Viral\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les causes infectieuses de diarrhée aiguë sont dominées par les virus (rotavirus surtout). Bactéries, parasites et champignons sont moins fréquents.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Etiologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nouveau-né GG, 3 jours de vie, vit à Krindjabo. La mère est très inquiète car le sexe de l'enfant est ambigu et il respire difficilement. Le médecin pense à une hyperplasie congénitale des surrénales.\",\n       \"text\": \"L'analyse des données révèle dans l'identification :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 données de dépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 données de dépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2 données de dépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 donnée de dépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 1 donnée de dépendance\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dans l'identification, la seule donnée de dépendance est le sexe ambigu (donnée anormale) ; les autres éléments d'identification sont des données d'indépendance.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diagnostic infirmier », Analyse et interprétation des données\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nouveau-né GG, 3 jours de vie, vit à Krindjabo. La mère est très inquiète car le sexe de l'enfant est ambigu et il respire difficilement. Le médecin pense à une hyperplasie congénitale des surrénales.\",\n       \"text\": \"L'analyse des données révèle :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 données d'indépendance + 3 données de dépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"4 données d'indépendance + 4 données de dépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 données d'indépendance + 6 données de dépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3 données d'indépendance + 5 données de dépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 3 données d'indépendance + 5 données de dépendance\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Indépendance : nom, âge, lieu d'habitation (3). Dépendance : sexe ambigu, respiration difficile, inquiétude de la mère, diagnostic d'hyperplasie congénitale des surrénales… La correction nationale retient 3 données d'indépendance et 5 de dépendance, cohérent avec les deux questions précédentes. Remarque : le détail des 5 données de dépendance n'est pas donné dans le cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diagnostic infirmier », Analyse et interprétation des données\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"À 5 minutes de vie, le nouveau-né T.P. avait une cyanose des extrémités, une fréquence cardiaque à 110 battements par minute, un cri vigoureux, une flexion des extrémités et une respiration régulière synchrone. Le score d'APGAR de T.P. est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"7\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"9\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 8\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Score d'APGAR : cyanose des extrémités = 1 ; FC 110 (> 100) = 2 ; cri vigoureux = 2 ; flexion des extrémités = 1 ; respiration régulière = 2. Total = 8.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Souffrance cérébrale du nouveau-né », Tableau du score d'Apgar\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont des signes retrouvés au cours d'un marasme chez l'enfant, sauf une. Cochez cette proposition.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Diarrhée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Regard vif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Anorexie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Alopécie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Anorexie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans le marasme, l'appétit est conservé : l'enfant est affamé. Diarrhée (de la faim), regard vif et alopécie font partie du tableau ; l'anorexie est l'intrus (elle caractérise plutôt le kwashiorkor).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Formes cliniques – Marasme\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont les composantes de la méthode soins mère-kangourou sauf une. Cochez cette proposition.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Suivi pour rechercher les signes de danger\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Contact peau à peau pour réchauffer\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nutrition (allaitement) pour éviter l'hypoglycémie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vaccination pour prévenir les infections\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Vaccination pour prévenir les infections\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La méthode kangourou comprend le contact peau à peau, l'allaitement (nutrition) et le suivi. La vaccination fait partie des soins habituels du nouveau-né, pas des composantes de la méthode. Remarque : dans le sujet, l'option C est coupée sur deux lignes ; elle a été réunie.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XVII « La méthode des soins mère kangourou », Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"G.D. a une température à 40 °C. À l'examen, G.D. est somnolent, avec un cri plaintif et un faciès pâle. Je conclus que G.D. ne tolère pas sa fièvre.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Somnolence, cri plaintif et faciès pâle (teint grisâtre) sont des signes de mauvaise tolérance de la fièvre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Examen physique – Signes de mauvaise tolérance\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez le nouveau-né prématuré, les petites lèvres, au niveau de la vulve, sont saillantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez la fille prématurée, les petites lèvres sont saillantes (non recouvertes par les grandes lèvres), signe d'immaturité.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né prématuré », Informations à rechercher à l'examen physique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La maladie des membranes hyalines chez le nouveau-né prématuré est la conséquence de son immaturité pulmonaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La maladie des membranes hyalines est due à l'immaturité pulmonaire du prématuré (défaut de production du surfactant).\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre VIII « Prématurité », Maladie des membranes hyalines\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour la prévention de la carence en fer chez le fœtus, je prescris à la gestante, durant toute la grossesse, du fer.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le fer et l'acide folique sont donnés à la gestante durant toute la grossesse (dès la 1re CPN jusqu'à l'accouchement) pour prévenir l'anémie.\\n\\nSource : Les 12 pratiques familiales essentielles (PFE), PFE n° 11 – Prévention de l'anémie ; L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né hypotrophe », Rôles de soins préventifs\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La solution sucrée à 10 % administrée à l'enfant malnutri est composée de 1 carreau de sucre et 50 mL d'eau potable.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un carreau de sucre pèse environ 5 g ; 5 g dans 50 ml donnent une solution à 10 % (10 g pour 100 ml), utilisée pour prévenir l'hypoglycémie de l'enfant malnutri. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"K.K., nourrisson de 13 mois pesant 9 kg, présente des signes sévères de déshydratation. Pour le réhydrater, je lui administre durant la première demi-heure du Ringer lactate à la quantité de 270 mL.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes sévères chez un enfant de plus de 12 mois : plan C, 30 ml/kg de Ringer lactate en 30 minutes puis 70 ml/kg en 2 h 30. 30 × 9 kg = 270 ml dans la première demi-heure.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan C : traiter rapidement la déshydratation sévère »\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né de dame P.L. est né à terme avec un poids de 1600 g. Pour la prévention de la maladie hémorragique du nouveau-né, j'administre en intramusculaire, avant la sortie de la maternité, 1 mg de vitamine K1.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale retient 1 mg de vitamine K1 en IM. Le module de néonatologie prévoit 1 mg si le poids est ≥ 1500 g et 0,5 mg en dessous. Remarque : le cours de santé infantile prévoit 0,5 mg si le poids est < 2500 g, et le cours du Dr Asse 5 mg ; les doses diffèrent selon les cours.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre XV « Les anémies néonatales », Traitement préventif – A la naissance\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le prématuré a des plis plantaires supérieurs aux 2/3 antérieurs.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez le prématuré, les stries plantaires sont absentes ou limitées à la partie antérieure ; des plis couvrant plus des 2/3 de la plante sont un signe de maturité. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Photothèque « Nouveau-né prématuré à J0 » (stries plantaires absentes)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le marasme survient le plus souvent chez l'enfant entre 18 et 36 mois.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le marasme survient plutôt entre 6 et 12 mois ; c'est le kwashiorkor qui survient entre 18 et 36 mois (sevrage). Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Facteurs étiologiques – Âge\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dose de vitamine K1 administrée au nouveau-né prématuré pour traiter la maladie hémorragique est de 10 mg en une injection intraveineuse pendant 4 jours.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Devant un nouveau-né qui saigne, l'agent de santé injecte 10 mg de vitamine K1 en IV ou en IM pendant 3 à 4 jours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Maladie hémorragique du nouveau-né », Rôles de soins curatifs\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né prématuré a une coloration rose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale retient « Faux ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Nouveau-né prématuré », Informations à rechercher à l'examen physique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nourrisson CB, sexe féminin, 3 ans, vit à Aboisso. Elle a une fièvre, tousse et est très enrhumée. Le médecin pense à une rhinopharyngite.\",\n       \"text\": \"Le problème infirmier de CB est une perturbation des échanges gazeux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La rhinopharyngite est une infection respiratoire haute (nez et gorge) : le problème est l'obstruction nasale (dégagement inefficace des voies aériennes), pas une perturbation des échanges gazeux, qui concerne les alvéoles.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Rhinopharyngite de l'enfant », Définition ; Glossaire du diagnostic infirmier\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Nourrisson CB, sexe féminin, 3 ans, vit à Aboisso. Elle a une fièvre, tousse et est très enrhumée. Le médecin pense à une rhinopharyngite.\",\n       \"text\": \"Pour la prise en charge du nourrisson CB ci-dessus, je collabore avec le médecin pour lui réaliser une radiographie du thorax.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale retient « Vrai ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Rhinopharyngite de l'enfant », Diagnostic positif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La vomique correspond à une expectoration brutale par la bouche de pus ou de sérosité provenant des voies respiratoires.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La vomique est l'expectoration brutale par la bouche de pus ou de sérosité venant des voies respiratoires ; il ne faut pas la confondre avec le vomissement.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Vomissements de l'enfant », Diagnostic différentiel\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"QQ présente un paludisme avec vomissements. Je lui administre un antiémétique pour ses vomissements. Le syndrome extrapyramidal grave qui survient chez l'enfant après administration de l'antiémétique se traite avec le diazépam.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le syndrome extrapyramidal est un effet secondaire des antiémétiques (métoclopramide…) ; pour le traiter, on administre du diazépam 0,5 mg/kg en perfusion lente dans du sérum glucosé.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Vomissements de l'enfant », Rôles curatifs – Antiémétisants\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la diarrhée aiguë, le nourrisson âgé de 5 mois reçoit, en plus de la réhydratation et de l'alimentation, un comprimé de zinc dosé à 20 mg par jour pendant 10 jours.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À 5 mois (moins de 6 mois), la dose de zinc est ½ comprimé de 20 mg, soit 10 mg par jour. 20 mg/j correspond aux enfants de 6 mois et plus. Faux.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan A », Donner du zinc\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson souffrant d'une diarrhée avec signes évidents de déshydratation est traité pendant les 4 premières heures au centre de santé, puis le relais est fait à domicile.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Plan B : réhydratation par SRO au centre de santé pendant 4 heures, puis réévaluation ; si les signes ont disparu, on passe au plan A (traitement à domicile).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Réhydratation – Plan B\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour une transfusion de 195 mL de culot globulaire en 4 heures, j'administre la transfusion à un débit de 12 gouttes/minute.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Formule du cours : débit (gouttes/min) = quantité (ml) ÷ (4 × durée en heures) = 195 ÷ (4 × 4) ≈ 12 gouttes/min.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Anémie aiguë de l'enfant », Rôle de soins curatifs – 3e situation (calcul du débit)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'apport journalier de lait thérapeutique F75 durant la réhabilitation nutritionnelle, chez l'enfant T.G. pesant 7 kg, est de 500 mL.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'apport de F75 est de 130 ml/kg/jour : pour 7 kg, 130 × 7 = 910 ml par jour, réparti en 6 à 8 repas. 500 ml est insuffisant. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Réhabilitation nutritionnelle – Laits thérapeutiques F75 et F100\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j8-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"B.T. est un nourrisson de 18 mois, admis pour difficulté respiratoire sifflante. Le médecin conclut au diagnostic de bronchiolite. Il s'agit d'une infection respiratoire aiguë basse d'origine bactérienne.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La bronchiolite est une IRA basse d'origine virale (VRS) ; le traitement antibiotique n'est pas justifié en première intention. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Infections respiratoires aiguës de l'enfant », Bronchiolite CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\",\n       \"sourceDoc\": \"Préparation D.E (J) · Pédiatrie · Prépa D.E J8 (IDE-SFM)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
